import nodemailer, { Transporter } from "nodemailer";
import { env, isProd } from "../config/env";

/**
 * Outbound transactional email over SMTP.
 *
 * Why this exists: Supabase's built-in mailer sends at most **2 emails per hour,
 * project-wide** — not per user. Two signups an hour across the entire platform,
 * with password resets drawing from the same bucket, so a handful of resets is
 * enough to starve registration. Supabase documents that sender as testing-only.
 * Auth codes are now generated by Supabase (`admin.generateLink`, which sends
 * nothing) and delivered from here instead.
 *
 * Flag-gated like `captcha.ts` and `whatsapp.ts`: with `SMTP_ENABLED=false`
 * nothing is sent and the message is logged, so local and preview environments
 * need no mail account. The one place that is *not* allowed to silently no-op is
 * production — see `sendEmail`.
 */

let transporter: Transporter | null = null;

const getTransport = (): Transporter => {
  if (transporter) return transporter;
  transporter = nodemailer.createTransport({
    host: env.smtpHost,
    port: env.smtpPort,
    secure: env.smtpSecure,
    auth: { user: env.smtpUser, pass: env.smtpPass },
    // A hung SMTP dial would otherwise hold the signup request open until the
    // client gives up, and the caller can't tell that apart from a bad code.
    connectionTimeout: 10_000,
    greetingTimeout: 10_000,
    socketTimeout: 20_000,
  });
  return transporter;
};

export interface SendEmailInput {
  to: string;
  subject: string;
  html: string;
  /** Plain-text alternative. Always send one — HTML-only mail scores as spam. */
  text: string;
}

/**
 * Strip anything that looks like a one-time code before a subject reaches a log.
 *
 * The subject deliberately leads with the code so it shows in a phone's
 * notification preview — which also means logging it verbatim writes live
 * verification codes into Render's retained logs. Anyone with dashboard access
 * could read a code and use it before the user does: an account-takeover path
 * that leaves no trace in the app itself.
 */
const redactCodes = (subject: string) => subject.replace(/\d{4,}/g, "******");

/**
 * Send one transactional email.
 *
 * Resolves on success. Throws only when the caller must not pretend the mail
 * went out — i.e. an auth code the user is now sitting on a screen waiting for.
 */
export const sendEmail = async ({ to, subject, html, text }: SendEmailInput): Promise<void> => {
  if (!env.smtpEnabled) {
    // Misconfiguration in production is worse than loud failure: every signup
    // would report "code sent" and no code would exist. Fail closed.
    if (isProd) {
      console.error("[email] SMTP_ENABLED=false in production — refusing to fake a send");
      throw new Error("Email delivery is not configured");
    }
    // Unredacted on purpose: this branch is dev-only (it throws in production
    // above), and printing the code is how you complete a signup with no mailbox.
    console.log(`[email] (disabled) would send to=${to} subject="${subject}"\n${text}`);
    return;
  }

  if (!env.smtpUser || !env.smtpPass) {
    console.error("[email] SMTP_ENABLED=true but SMTP_USER/SMTP_PASS are unset");
    throw new Error("Email delivery is not configured");
  }

  try {
    const info = await getTransport().sendMail({
      from: { name: env.emailFromName, address: env.emailFrom },
      to,
      subject,
      text,
      html,
    });
    console.log(
      `[email] sent to=${to} subject="${redactCodes(subject)}" messageId=${info.messageId}`
    );
  } catch (err: any) {
    // Surface the SMTP response code — "did it go out?" should be answerable
    // from the logs without a repro, the way the Supabase send errors were.
    console.error(`[email] send FAILED to=${to} subject="${redactCodes(subject)}"`, {
      code: err?.code,
      responseCode: err?.responseCode,
      command: err?.command,
      message: err?.message,
    });
    throw new Error("Could not send the email. Please try again.");
  }
};

/**
 * Check the SMTP credentials at boot rather than discovering they are wrong on
 * someone's first signup. Never throws — a mail provider having a bad minute
 * must not stop the API coming up.
 */
export const verifyEmailTransport = async (): Promise<void> => {
  if (!env.smtpEnabled) {
    console.log("[email] SMTP disabled — auth codes will be logged, not sent");
    return;
  }
  try {
    await getTransport().verify();
    console.log(`[email] SMTP ready host=${env.smtpHost}:${env.smtpPort} from=${env.emailFrom}`);
  } catch (err: any) {
    console.error("[email] SMTP verify failed — sends will fail until fixed:", err?.message);
  }
};
